import { Inject, Injectable, PLATFORM_ID, TransferState, makeStateKey } from '@angular/core';
import { catchError, tap } from 'rxjs/operators';
import { HttpClient } from '@angular/common/http';
import { Observable, of, throwError } from 'rxjs';
import { isPlatformBrowser, isPlatformServer } from '@angular/common';
import { environment } from '../../../environments/environment';

@Injectable({
  providedIn: 'root'
})
export class BannerService {
  private readonly endpoint = `${environment.baseUrl}/api/banner/getAllBanner`;

  constructor(
    private readonly http: HttpClient,
    private readonly transferState: TransferState,
    @Inject(PLATFORM_ID) private readonly platformId: Object
  ) { }


  getHomeBanner = (data: any): Observable<any> => {
    const stateKey = makeStateKey<any>(`banner-home:${JSON.stringify(data)}`);

    if (isPlatformBrowser(this.platformId) && this.transferState.hasKey(stateKey)) {
      const cachedResponse = this.transferState.get<any>(stateKey, null);
      this.transferState.remove(stateKey);
      return of(cachedResponse);
    }

    return this.http.post(this.endpoint, data).pipe(
      tap((response) => {
        if (isPlatformServer(this.platformId)) {
          this.transferState.set(stateKey, response);
        }
      }),
      catchError((err) => {
        return throwError(err);
      })
    );
  };

}
